1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Reading an image back — the block-fetching glue `minixrs-mfs` deliberately
4	//! omits, over a `&[u8]` instead of over a block device.
5	//!
6	//! Slice 5.8's MFS server writes the BDEV-backed equivalent of exactly these
7	//! functions: same decoders, same zone resolver, same directory walk, with
8	//! [`block`] replaced by a `BDEV_READ`. That symmetry is the point — the round
9	//! trip below exercises the reader the server will use, not a second reader
10	//! written to agree with the writer.
11	
12	use minixrs_mfs::MFS_BLOCK_SIZE;
13	use minixrs_mfs::dirent::iter_block;
14	use minixrs_mfs::inode::{Inode, ROOT_INODE};
15	use minixrs_mfs::layout::{Layout, imap_bit, layout, zmap_bit};
16	use minixrs_mfs::read::{
17	    ZoneLookup, inode_at, inode_location, zone_for_offset, zone_from_indirect,
18	};
19	use minixrs_mfs::superblock::{SUPER_OFFSET, SUPER_ON_DISK_LEN, Superblock};
20	
21	/// Borrow block `b` of `img`. `None` past the end of the image.
22	pub fn block(img: &[u8], b: u32) -> Option<&[u8]> {
23	    let start = (b as usize).checked_mul(MFS_BLOCK_SIZE)?;
24	    img.get(start..start.checked_add(MFS_BLOCK_SIZE)?)
25	}
26	
27	/// Decode the superblock. `None` if the image is too short or the superblock is
28	/// not a MinixFS v3 this build reads.
29	pub fn superblock(img: &[u8]) -> Option<Superblock> {
30	    let sb = Superblock::from_le_bytes(img.get(SUPER_OFFSET..SUPER_OFFSET + SUPER_ON_DISK_LEN)?)?;
31	    sb.validate().ok()?;
32	    Some(sb)
33	}
34	
35	/// The image's layout, derived from its own superblock.
36	pub fn image_layout(img: &[u8]) -> Option<Layout> {
37	    let sb = superblock(img)?;
38	    Some(layout(sb.ninodes, sb.zones, MFS_BLOCK_SIZE))
39	}
40	
41	/// Fetch inode `ino`.
42	pub fn inode(img: &[u8], ino: u32) -> Option<Inode> {
43	    let l = image_layout(img)?;
44	    let (b, slot) = inode_location(ino, &l, MFS_BLOCK_SIZE)?;
45	    inode_at(block(img, b)?, slot)
46	}
47	
48	/// Read a file's (or directory's) contents, honouring holes.
49	///
50	/// A hole reads as zeroes — that is what a hole *means* — while an offset past
51	/// what the format can address is `None`, never silent zeroes. That distinction is
52	/// the reason `zone_for_offset` has both a `Hole` and an `OutOfRange`.
53	pub fn read_inode_bytes(img: &[u8], ino: &Inode) -> Option<Vec<u8>> {
54	    let size = usize::try_from(ino.size).ok()?;
55	    let mut out = Vec::with_capacity(size);
56	    let mut off = 0usize;
57	    while off < size {
58	        let want = (size - off).min(MFS_BLOCK_SIZE);
59	        match zone_for_offset(ino, off as u64, MFS_BLOCK_SIZE) {
60	            ZoneLookup::Direct(z) => out.extend_from_slice(&block(img, z)?[..want]),
61	            ZoneLookup::Indirect { zone, slot } => {
62	                let z = zone_from_indirect(block(img, zone)?, slot)?;
63	                if z == 0 {
64	                    out.extend(std::iter::repeat_n(0u8, want));
65	                } else {
66	                    out.extend_from_slice(&block(img, z)?[..want]);
67	                }
68	            }
69	            ZoneLookup::Hole => out.extend(std::iter::repeat_n(0u8, want)),
70	            ZoneLookup::OutOfRange => return None,
71	        }
72	        off += want;
73	    }
74	    Some(out)
75	}
76	
77	/// Resolve an absolute path to `(inode number, inode)`.
78	///
79	/// `"/"` is the root. Each component is looked up through the directory's own
80	/// entries, so a path that names a file as an intermediate component fails rather
81	/// than reading a file's bytes as directory entries.
82	pub fn lookup(img: &[u8], path: &str) -> Option<(u32, Inode)> {
83	    let mut ino = ROOT_INODE;
84	    let mut node = inode(img, ino)?;
85	    for component in path.split('/').filter(|c| !c.is_empty()) {
86	        if !node.is_dir() {
87	            return None;
88	        }
89	        let bytes = read_inode_bytes(img, &node)?;
90	        ino = bytes
91	            .chunks(MFS_BLOCK_SIZE)
92	            .flat_map(iter_block)
93	            .find(|e| e.name_str() == component)
94	            .map(|e| e.ino)?;
95	        node = inode(img, ino)?;
96	    }
97	    Some((ino, node))
98	}
99	
100	/// Read a regular file's contents by path.
101	pub fn read_file(img: &[u8], path: &str) -> Option<Vec<u8>> {
102	    let (_, node) = lookup(img, path)?;
103	    if !node.is_reg() {
104	        return None;
105	    }
106	    read_inode_bytes(img, &node)
107	}
108	
109	/// List a directory's entry names by path, in on-disk order (so `.` and `..`
110	/// come first).
111	pub fn read_dir(img: &[u8], path: &str) -> Option<Vec<String>> {
112	    let (_, node) = lookup(img, path)?;
113	    if !node.is_dir() {
114	        return None;
115	    }
116	    let bytes = read_inode_bytes(img, &node)?;
117	    Some(
118	        bytes
119	            .chunks(MFS_BLOCK_SIZE)
120	            .flat_map(iter_block)
121	            .map(|e| e.name_str().to_string())
122	            .collect(),
123	    )
124	}
125	
126	/// Is inode `ino` marked allocated in the inode bitmap?
127	pub fn imap_bit_set(img: &[u8], ino: u32) -> Option<bool> {
128	    let l = image_layout(img)?;
129	    bit_set(img, l.imap_start, imap_bit(ino))
130	}
131	
132	/// Is zone `zone` marked allocated in the zone bitmap? `None` for a zone below
133	/// the first data zone, which has no bit.
134	pub fn zmap_bit_set(img: &[u8], zone: u32) -> Option<bool> {
135	    let l = image_layout(img)?;
136	    bit_set(img, l.zmap_start, zmap_bit(zone, l.first_data_zone)?)
137	}
138	
139	fn bit_set(img: &[u8], start: u32, bit: u32) -> Option<bool> {
140	    let byte = (start as usize).checked_mul(MFS_BLOCK_SIZE)? + (bit as usize) / 8;
141	    Some(img.get(byte)? & (1 << (bit % 8)) != 0)
142	}
143	
144	#[cfg(test)]
145	mod tests {
146	    use super::*;
147	    use crate::image::{
148	        HDR_BLOCK_SIZE_OFF, HDR_BLOCKS_OFF, HDR_LABEL_OFF, HDR_MFS_MAGIC_OFF, IMAGE_HDR_LEN,
149	        IMAGE_LABEL, IMAGE_LABEL_LEN, IMAGE_TAIL_LABEL, MkfsError, ROOTFS_IMAGE_BLOCKS,
150	        ROOTFS_IMAGE_BYTES, ROOTFS_TAIL_BLOCK, build_image,
151	    };
152	    use crate::manifest::Manifest;
153	    use minixrs_mfs::inode::{NR_DIRECT_ZONES, SINGLE_INDIRECT_SLOT};
154	
155	    /// A file large enough to need the indirect block: nine blocks, two past the
156	    /// seven direct zones.
157	    const BIG_LEN: usize = (NR_DIRECT_ZONES + 2) * MFS_BLOCK_SIZE;
158	
159	    fn big_bytes() -> Vec<u8> {
160	        // Position-dependent and non-repeating over a block, so a copy that lost,
161	        // duplicated, or reordered a block changes the bytes.
162	        (0..BIG_LEN).map(|i| (i % 251) as u8).collect()
163	    }
164	
165	    /// An image shaped like the real root filesystem: a `/bin` holding one large
166	    /// file, and an `/etc` holding a small one, an empty one, and a one-byte one.
167	    fn sample() -> Vec<u8> {
168	        let mut m = Manifest::new();
169	        m.add("/bin/hello", big_bytes())
170	            .add("/etc/motd", b"minix.rs rootfs motd\n".to_vec())
171	            .add("/etc/empty", Vec::new())
172	            .add("/etc/one", vec![0xA5]);
173	        build_image(&m).expect("the sample manifest fits the fixed image")
174	    }
175	
176	    #[test]
177	    fn the_image_is_the_fixed_size_and_its_superblock_agrees() {
178	        let img = sample();
179	        assert_eq!(img.len(), ROOTFS_IMAGE_BYTES);
180	
181	        let sb = superblock(&img).expect("the superblock decodes and validates");
182	        assert_eq!(sb.validate(), Ok(()));
183	        assert_eq!(sb.zones, ROOTFS_IMAGE_BLOCKS);
184	        assert_eq!(sb.zones as usize, img.len() / MFS_BLOCK_SIZE);
185	        assert_eq!(sb.block_size as usize, MFS_BLOCK_SIZE);
186	        assert_eq!(sb.log_zone_size, 0);
187	    }
188	
189	    #[test]
190	    fn the_root_directory_lists_dot_dotdot_and_every_subdirectory() {
191	        let img = sample();
192	        assert_eq!(
193	            read_dir(&img, "/").unwrap(),
194	            [".", "..", "bin", "etc"],
195	            "root's entries, in on-disk order"
196	        );
197	        assert_eq!(
198	            read_dir(&img, "/etc").unwrap(),
199	            [".", "..", "motd", "empty", "one"],
200	            "a subdirectory's entries follow manifest order"
201	        );
202	        assert_eq!(read_dir(&img, "/bin").unwrap(), [".", "..", "hello"]);
203	    }
204	
205	    #[test]
206	    fn every_directory_is_a_directory_and_every_file_is_a_file() {
207	        let img = sample();
208	        for dir in ["/", "/bin", "/etc"] {
209	            assert!(lookup(&img, dir).unwrap().1.is_dir(), "{dir}");
210	            assert_eq!(read_file(&img, dir), None, "{dir} is not a regular file");
211	        }
212	        for file in ["/bin/hello", "/etc/motd", "/etc/empty", "/etc/one"] {
213	            assert!(lookup(&img, file).unwrap().1.is_reg(), "{file}");
214	            assert_eq!(read_dir(&img, file), None, "{file} is not a directory");
215	        }
216	    }
217	
218	    #[test]
219	    fn a_file_larger_than_seven_zones_uses_the_indirect_block() {
220	        // The arm that would otherwise be dead in the musl-sysroot-absent build,
221	        // where `hello` is a 15 KB `worker` ELF that fits the direct zones. This is
222	        // why `/etc/pattern` exists in the real manifest, and it is what this test
223	        // stands in for.
224	        let img = sample();
225	        let (_, node) = lookup(&img, "/bin/hello").unwrap();
226	        assert_eq!(node.size as usize, BIG_LEN);
227	        assert_ne!(
228	            node.zone[SINGLE_INDIRECT_SLOT], 0,
229	            "a nine-block file must have an indirect block"
230	        );
231	        for slot in 0..NR_DIRECT_ZONES {
232	            assert_ne!(
233	                node.zone[slot], 0,
234	                "direct zone {slot} must be filled first"
235	            );
236	        }
237	        assert_eq!(read_file(&img, "/bin/hello").unwrap(), big_bytes());
238	    }
239	
240	    #[test]
241	    fn a_small_file_round_trips_byte_for_byte() {
242	        let img = sample();
243	        assert_eq!(
244	            read_file(&img, "/etc/motd").unwrap(),
245	            b"minix.rs rootfs motd\n"
246	        );
247	    }
248	
249	    #[test]
250	    fn the_div_ceil_boundary_files_round_trip() {
251	        // A one-byte file occupies exactly one block; a zero-byte file occupies
252	        // none at all, which is the case `len.div_ceil(BLOCK_SIZE)` gets wrong if
253	        // it is written as `len / BLOCK_SIZE + 1`.
254	        let img = sample();
255	        assert_eq!(read_file(&img, "/etc/one").unwrap(), vec![0xA5]);
256	        assert_eq!(read_file(&img, "/etc/empty").unwrap(), Vec::<u8>::new());
257	
258	        let (_, one) = lookup(&img, "/etc/one").unwrap();
259	        assert_eq!(one.size, 1);
260	        assert_ne!(one.zone[0], 0, "a one-byte file still needs a zone");
261	
262	        let (_, empty) = lookup(&img, "/etc/empty").unwrap();
263	        assert_eq!(empty.size, 0);
264	        assert_eq!(empty.zone, [0u32; minixrs_mfs::inode::NR_TZONES]);
265	    }
266	
267	    #[test]
268	    fn a_path_that_does_not_exist_resolves_to_nothing() {
269	        let img = sample();
270	        for missing in ["/bin/nope", "/nope/hello", "/etc/motd/x"] {
271	            assert_eq!(lookup(&img, missing), None, "{missing}");
272	        }
273	    }
274	
275	    /// **This is the test that licenses the boot markers to check the image header
276	    /// instead of the superblock.** The `memory` driver is a *block* driver and must
277	    /// not depend on the filesystem format, so it verifies the header — which is only
278	    /// a meaningful check if the header cannot disagree with the real superblock.
279	    #[test]
280	    fn the_image_header_agrees_with_the_real_superblock() {
281	        let img = sample();
282	        let sb = superblock(&img).unwrap();
283	
284	        assert_eq!(
285	            &img[HDR_LABEL_OFF..HDR_LABEL_OFF + IMAGE_LABEL_LEN],
286	            &IMAGE_LABEL
287	        );
288	        assert_eq!(
289	            u32::from_le_bytes(img[HDR_BLOCKS_OFF..HDR_BLOCKS_OFF + 4].try_into().unwrap()),
290	            sb.zones
291	        );
292	        assert_eq!(
293	            u32::from_le_bytes(
294	                img[HDR_BLOCK_SIZE_OFF..HDR_BLOCK_SIZE_OFF + 4]
295	                    .try_into()
296	                    .unwrap()
297	            ) as u16,
298	            sb.block_size
299	        );
300	        assert_eq!(
301	            i32::from_le_bytes(
302	                img[HDR_MFS_MAGIC_OFF..HDR_MFS_MAGIC_OFF + 4]
303	                    .try_into()
304	                    .unwrap()
305	            ),
306	            i32::from(sb.magic)
307	        );
308	    }
309	
310	    #[test]
311	    fn the_header_sits_in_the_boot_block_and_leaves_the_superblock_alone() {
312	        // The header lives in bytes 0..32, MinixFS's superblock at 1024. If the
313	        // header ever grew into it, `superblock()` above would already be failing —
314	        // but state the gap, because "32 < 1024" is the whole reason this design
315	        // works.
316	        assert_eq!(IMAGE_HDR_LEN.min(SUPER_OFFSET), IMAGE_HDR_LEN);
317	        let img = sample();
318	        assert!(
319	            img[IMAGE_HDR_LEN..SUPER_OFFSET].iter().all(|&b| b == 0),
320	            "the rest of the boot block must stay zero"
321	        );
322	    }
