324	    #[test]
325	    fn the_tail_label_sits_in_the_reserved_last_block() {
326	        // The tail is what distinguishes "the blob was copied" from "the blob's
327	        // first page was copied 256 times" — so it must be at the far end, and no
328	        // file may ever be allocated there.
329	        let img = sample();
330	        let off = ROOTFS_TAIL_BLOCK as usize * MFS_BLOCK_SIZE;
331	        assert_eq!(off, (ROOTFS_IMAGE_BLOCKS as usize - 1) * 4096);
332	        assert_eq!(&img[off..off + IMAGE_LABEL_LEN], &IMAGE_TAIL_LABEL);
333	        assert_ne!(&img[off..off + IMAGE_LABEL_LEN], &IMAGE_LABEL);
334	
335	        assert_eq!(
336	            zmap_bit_set(&img, ROOTFS_TAIL_BLOCK),
337	            Some(true),
338	            "the tail block must be marked allocated so no file can land on it"
339	        );
340	    }
341	
342	    #[test]
343	    fn every_allocated_inode_and_zone_is_marked_in_the_bitmaps() {
344	        let img = sample();
345	        // Root, /bin, /etc, then the four files: inodes 1..=7.
346	        for ino in 1..=7 {
347	            assert_eq!(imap_bit_set(&img, ino), Some(true), "inode {ino}");
348	        }
349	        assert_eq!(imap_bit_set(&img, 0), Some(true), "inode 0 is reserved");
350	        assert_eq!(imap_bit_set(&img, 8), Some(false), "inode 8 is free");
351	
352	        // Every zone a file actually uses.
353	        let (_, hello) = lookup(&img, "/bin/hello").unwrap();
354	        for z in hello.zone.iter().copied().filter(|&z| z != 0) {
355	            assert_eq!(zmap_bit_set(&img, z), Some(true), "zone {z}");
356	        }
357	    }
358	
359	    #[test]
360	    fn an_over_large_manifest_is_refused_with_exact_numbers() {
361	        // Two files of ~600 KB each cannot fit a 1 MiB image. The error names the
362	        // shortfall so the fix is one constant.
363	        let mut m = Manifest::new();
364	        m.add("/bin/a", vec![1u8; 600 * 1024])
365	            .add("/bin/b", vec![2u8; 600 * 1024]);
366	        match build_image(&m) {
367	            Err(MkfsError::TooBig { needed, have }) => {
368	                assert!(needed > have, "needed {needed} have {have}");
369	                assert!(
370	                    have < ROOTFS_IMAGE_BLOCKS,
371	                    "the free zones exclude metadata and the reserved tail"
372	                );
373	            }
374	            other => panic!("expected TooBig, got {other:?}"),
375	        }
376	    }
377	
378	    #[test]
379	    fn the_build_is_deterministic() {
380	        // `kernel/build.rs` embeds this image in the kernel ELF, so two builds of
381	        // the same manifest must produce identical bytes.
382	        assert_eq!(sample(), sample());
383	    }
384	}
