1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Locating an inode, and resolving a file offset to a zone.
4	//!
5	//! Every function here takes bytes the caller already fetched and returns *what
6	//! to fetch next*, never fetching anything itself. That is what lets slice 5.8's
7	//! MFS server drive the same code over `BDEV_READ` while `tools/mkfs-mfs` drives
8	//! it over a `Vec<u8>`, with no trait, no I/O abstraction, and no fake device in
9	//! the tests.
10	//!
11	//! ## Why `OutOfRange` is explicit
12	//!
13	//! [`zone_for_offset`] distinguishes a **hole** (a zone pointer that is legitimately
14	//! zero — the file is sparse there, and reading it yields zeroes) from an offset
15	//! **past the single-indirect span**, which is a caller bug. Collapsing the second
16	//! into "read zeroes" is how a filesystem silently returns wrong data; the D4
17	//! documented-`EINVAL` discipline says the caller hears about it.
18	//!
19	//! ## Why double-indirect is not implemented
20	//!
21	//! Seven direct zones plus one single-indirect block of `block_size / 4` pointers
22	//! is `7 + 1024` zones at a 4 KiB block size — **4.03 MiB**, which is larger than
23	//! any image this filesystem holds (the slice-5.7 root image is 1 MiB, and the VA
24	//! window reserved for it is 4 MiB). A double-indirect reader would therefore be
25	//! code no test could reach with a real image. [`ZoneLookup::OutOfRange`] is the
26	//! honest answer until an image needs one.
27	
28	use crate::inode::{INODE_SIZE, Inode, NR_DIRECT_ZONES, SINGLE_INDIRECT_SLOT};
29	use crate::layout::Layout;
30	
31	/// What backs a given file offset.
32	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
33	pub enum ZoneLookup {
34	    /// The zone is named directly by the inode. Always non-zero.
35	    Direct(u32),
36	    /// The zone number lives at `slot` of the indirect block at zone `zone`.
37	    /// Fetch that block and pass it to [`zone_from_indirect`].
38	    Indirect { zone: u32, slot: usize },
39	    /// A hole: the relevant pointer is zero, so this range of the file has never
40	    /// been written and reads as zeroes.
41	    Hole,
42	    /// Past what the single-indirect span can address. See the module docs.
43	    OutOfRange,
44	}
45	
46	/// Zone pointers one indirect block can hold.
47	pub fn ptrs_per_block(block_size: usize) -> usize {
48	    block_size / 4
49	}
50	
51	/// Which block of the inode table holds inode `ino`, and its slot within it.
52	///
53	/// `None` for inode 0 (which does not exist) or an inode past the table. The
54	/// bound comes from `layout.inode_blocks`, so a caller cannot read an inode out of
55	/// the first data block by asking for one past the end.
56	pub fn inode_location(ino: u32, layout: &Layout, block_size: usize) -> Option<(u32, usize)> {
57	    if ino == 0 {
58	        return None;
59	    }
60	    let per_block = (block_size / INODE_SIZE) as u32;
61	    if per_block == 0 {
62	        return None;
63	    }
64	    let index = ino - 1;
65	    let block = layout.inode_start.checked_add(index / per_block)?;
66	    if block >= layout.inode_start.checked_add(layout.inode_blocks)? {
67	        return None;
68	    }
69	    Some((block, (index % per_block) as usize))
70	}
71	
72	/// Decode the inode at `slot` of a fetched inode-table block.
73	///
74	/// `None` if the slot runs past the block — which is how a caller that mixed up
75	/// `block_size` finds out, rather than by reading the next inode's bytes.
76	pub fn inode_at(inode_block: &[u8], slot: usize) -> Option<Inode> {
77	    let start = slot.checked_mul(INODE_SIZE)?;
78	    let end = start.checked_add(INODE_SIZE)?;
79	    Inode::from_le_bytes(inode_block.get(start..end)?)
80	}
81	
82	/// Resolve byte offset `off` within `inode` to the zone that backs it.
83	///
84	/// `off` is **not** checked against `inode.size`: that is the caller's policy
85	/// decision (a reader clamps to the size, `fsck` does not), and mixing it in here
86	/// would make a hole past EOF indistinguishable from a hole inside the file.
87	pub fn zone_for_offset(inode: &Inode, off: u64, block_size: usize) -> ZoneLookup {
88	    if block_size == 0 {
89	        return ZoneLookup::OutOfRange;
90	    }
91	    let index = off / block_size as u64;
92	
93	    if index < NR_DIRECT_ZONES as u64 {
94	        let zone = inode.zone[index as usize];
95	        return if zone == 0 {
96	            ZoneLookup::Hole
97	        } else {
98	            ZoneLookup::Direct(zone)
99	        };
100	    }
101	
102	    let slot = index - NR_DIRECT_ZONES as u64;
103	    if slot >= ptrs_per_block(block_size) as u64 {
104	        return ZoneLookup::OutOfRange;
105	    }
106	    let indirect = inode.zone[SINGLE_INDIRECT_SLOT];
107	    if indirect == 0 {
108	        // No indirect block at all: everything it would have covered is a hole.
109	        return ZoneLookup::Hole;
110	    }
111	    ZoneLookup::Indirect {
112	        zone: indirect,
113	        slot: slot as usize,
114	    }
115	}
116	
117	/// Read zone pointer `slot` out of a fetched indirect block.
118	///
119	/// `None` if the slot runs past the block. `Some(0)` is a **hole**, not an error:
120	/// an indirect block's unused entries are zero, exactly like an inode's.
121	pub fn zone_from_indirect(block: &[u8], slot: usize) -> Option<u32> {
122	    let start = slot.checked_mul(4)?;
123	    let b = block.get(start..start.checked_add(4)?)?;
124	    Some(u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
125	}
126	
127	#[cfg(test)]
128	mod tests {
129	    use super::*;
130	    use crate::inode::{I_REGULAR, NR_TZONES, ROOT_INODE};
131	    use crate::layout::layout;
132	
133	    const BS: usize = crate::MFS_BLOCK_SIZE;
134	
135	    #[test]
136	    fn ptrs_per_block_is_a_thousand_and_twenty_four_at_four_kib() {
137	        assert_eq!(ptrs_per_block(BS), 1024);
138	        assert_eq!(ptrs_per_block(1024), 256);
139	    }
140	
141	    #[test]
142	    fn the_root_inode_is_the_first_slot_of_the_first_inode_block() {
143	        let l = layout(64, 256, BS);
144	        assert_eq!(inode_location(ROOT_INODE, &l, BS), Some((l.inode_start, 0)));
145	    }
146	
147	    #[test]
148	    fn inodes_fill_a_block_then_move_to_the_next() {
149	        // 64 inodes per 4 KiB block. Inode 64 is the last slot of block 0 of the
150	        // table; inode 65 would be the first slot of block 1 — but this geometry
