99	/// A deterministic, non-trivial byte pattern. Deterministic so PM's checksum is
100	/// a fixed value across runs; non-trivial (not `i`, not a constant) so a copy
101	/// that lost or duplicated a chunk still changes the sum.
102	const fn grant_test_pattern() -> [u8; GRANT_TEST_LEN] {
103	    let mut b = [0u8; GRANT_TEST_LEN];
104	    let mut i = 0;
105	    while i < GRANT_TEST_LEN {
106	        b[i] = (i as u8).wrapping_mul(37).wrapping_add(11);
107	        i += 1;
108	    }
109	    b
110	}
