114	/// The line VFS asks TTY to print. In `.rodata` (a `static`, not `static mut`),
115	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant.
116	static TTY_BANNER: [u8; 35] = *b"minix.rs vfs: hello via CDEV_WRITE\n";
