218	/// Serve one `VFS_WRITE`. Returns the reply `m_type`: bytes written (`>= 0`), or
219	/// a negative errno.
220	///
221	/// The checks, in order — each is the first thing that can be wrong given the
222	/// ones before it:
223	///
224	/// 1. The descriptor resolves, through the caller's own row of the fd table. The
225	///    caller is named by the kernel-stamped `m_source`, so a client cannot ask
226	///    about another process's descriptors.
227	/// 2. `len < 0` → `EINVAL`. Left unchecked it would widen into a ~16 EiB `u64`
228	///    byte count for the grant.
229	/// 3. `len == 0` → `0`, a legal empty write. Deliberately *before* the grant, so
230	///    a client polling with `len = 0` gets no grant issued at all and cannot use
231	///    it to probe the granting path. TTY applies the same rule one layer down.
232	/// 4. The buffer lies in the user address range. This is `user_range_ok`, the
233	///    no-alignment variant grants use — a `write()` buffer is a byte buffer.
234	///    Defence in depth rather than the load-bearing gate: the kernel's copy
235	///    engine walks the caller's page tables and answers `EFAULT` for anything
236	///    unmapped regardless (D5), which is what makes a bad pointer an errno here
237	///    instead of a fault in the caller.
238	///
239	/// Then the grant. `caller_e` is the **kernel-stamped `m_source`** — the one fact
240	/// in this whole request a client cannot forge. VFS holds `SYS_PROC`, which is
241	/// what makes a magic grant legal for it; taking the owner from the payload
242	/// instead would let any VFS client aim TTY's privileged `SYS_SAFECOPY` at a
243	/// third party's address space through VFS. There is no payload field for it, and
244	/// there must never be one.
245	#[cfg_attr(test, allow(dead_code))]
246	fn do_write(
247	    caller_e: Endpoint,
248	    msg: &Message,
249	    grants: &mut GrantPool<GRANT_SLOTS>,
250	    tty: Endpoint,
251	) -> i32 {
252	    let req = write::parse(msg);
253	
254	    let minor = match fd::resolve(endpoint_proc(caller_e).get(), req.fd) {
255	        Ok(Fd::CharDev { minor }) => minor,
256	        // `resolve` maps a closed descriptor to `EBADF` itself, so this arm is
257	        // unreachable today. It exists so slice 5.8's regular-file variant shows
258	        // up as a compile error to be routed, not a silent fallthrough.
259	        Ok(Fd::Unused) => return EBADF,
260	        Err(e) => return e,
261	    };
262	
263	    let len = match write::validate(req.len, req.buf) {
264	        Ok(len) => len,
265	        Err(e) => return e,
266	    };
267	    if len == 0 {
268	        // A legal empty write. No grant is issued, so a client polling with
269	        // `len = 0` cannot use it to probe the granting path.
270	        return 0;
271	    }
272	
273	    // The single-copy hop: the grant names the *caller's* memory, so the kernel
274	    // moves the bytes from the caller straight into the driver.
275	    let gid = match grants.grant_magic(tty, caller_e, req.buf, len as u64, CPF_READ) {
276	        Ok(gid) => gid,
277	        // Verbatim: `ENOMEM` (VFS is out of grant slots) and a `SYS_SETGRANT`
278	        // failure are different problems, and neither is the client's fault.
279	        Err(e) => return e,
280	    };
281	    let written = write_all(tty, minor, gid, len);
282	    let _ = grants.revoke(gid);
283	    written
284	}
285	
286	/// Drive `CDEV_WRITE` until `len` bytes are out, and report the total.
287	///
288	/// This is the IPC half only: every decision about when to stop and what to
289	/// report lives in [`write::advance`], which is where its rules are documented and
290	/// unit-tested. Two of those rules — a driver reporting `0`, and a driver
291	/// reporting more than it was asked for — are unreachable through a working TTY,
292	/// so keeping them out of this loop is what makes them testable at all.
293	///
294	/// `len > 0` on entry (`do_write` returns early on an empty write), so at least
295	/// one request always goes out and `len - off` is never zero.
296	#[cfg_attr(test, allow(dead_code))]
297	fn write_all(tty: Endpoint, minor: i32, gid: i32, len: usize) -> i32 {
298	    let mut off = 0usize;
299	    loop {
300	        let n = cdev_write(tty, minor, gid, (len - off) as i32, off as u64);
301	        match write::advance(off, len, n) {
302	            write::Step::More(next) => off = next,
303	            write::Step::Done(rc) => return rc,
304	        }
305	    }
306	}
307	
308	/// Reply to a SENDREC caller: stamp `m_type`, zero `m_source` (the kernel
309	/// overwrites it on delivery), and SEND the message back. A copy of TTY's, for
310	/// the reason TTY's exists.
311	#[cfg_attr(test, allow(dead_code))]
312	fn reply(target_e: Endpoint, msg: &mut Message, m_type: i32) {
313	    msg.m_type = m_type;
314	    msg.m_source = 0;
315	    let _ = ipc_send(target_e, msg);
316	}
