318	/// Slice 5.2 demo: direct-grant [`GRANT_TEST_BUF`] to PM and tell PM about it.
319	///
320	/// The grant id travels **in-band**, in the `PM_GRANT_TEST` payload, which is
321	/// how grant ids really travel — `CDEV_WRITE {minor, grant_id, len, offset}` has
322	/// the same shape, and takes its granter from `m_source` for the same reason. DS
323	/// could not carry one: `DS_PUBLISH` registers the kernel-stamped `m_source` and
324	/// ignores the payload, which is exactly its anti-spoof property.
325	///
326	/// `ipc_send` blocks until PM's receive loop picks the message up, so the demo
327	/// is self-synchronizing — no assumption is made about the two servers' SEF init
328	/// ordering. There is no cycle: VFS's own init only SENDRECs DS, and PM never
329	/// sends to VFS.
330	///
331	/// The buffer's raw address rides along too, so PM can read the same bytes a
332	/// second time with the ungranted `SYS_COPY` and compare.
333	///
334	/// A **second** grant over the same read-only buffer goes out claiming
335	/// `CPF_WRITE` — a granter lying about what its own memory permits. Nothing
336	/// stops a granter writing that entry, and the kernel copies through its own
337	/// HHDM alias where EL0 permission bits do not apply, so the only thing between
338	/// that lie and a corrupted `.rodata` page is the copy engine's explicit
339	/// `Prot::writable` check. PM probes it (`grant_denials`); this is the grant-path
340	/// analogue of slice 5.1's fourth bad-pointer probe.
341	///
342	/// Best-effort throughout: a failure here must not stop VFS from serving.
343	#[cfg_attr(test, allow(dead_code))]
344	fn grant_test(grants: &mut GrantPool<GRANT_SLOTS>) {
345	    let pm = boot_endpoint(PM_PROC_NR);
346	    let addr = (&raw const GRANT_TEST_BUF) as usize as u64;
347	    let len = GRANT_TEST_LEN as u64;
348	    let (Ok(gid), Ok(rw_gid)) = (
349	        grants.grant_direct(pm, addr, len, CPF_READ),
350	        grants.grant_direct(pm, addr, len, CPF_READ | CPF_WRITE),
351	    ) else {
352	        return;
353	    };
354	
355	    // No granter field: PM reads that off the kernel-stamped `m_source`, so
356	    // nothing in this payload can redirect PM's privileged copies at a third
357	    // party.
358	    let mut msg = Message {
359	        m_source: 0,
360	        m_type: PM_GRANT_TEST,
361	        payload: [0u8; 96],
362	    };
363	    msg.payload[0..4].copy_from_slice(&gid.to_ne_bytes());
364	    msg.payload[4..8].copy_from_slice(&(GRANT_TEST_LEN as i32).to_ne_bytes());
365	    msg.payload[8..12].copy_from_slice(&rw_gid.to_ne_bytes());
366	    msg.payload[16..24].copy_from_slice(&addr.to_ne_bytes());
367	    let _ = ipc_send(pm, &mut msg);
368	}
369	
370	/// Slice 5.3 demo: drive the TTY console driver over `CDEV_WRITE` directly.
371	///
372	/// Kept as a regression battery now that [`do_write`] is the real path, because
373	/// it proves three contracts the real path does not reach: the direct-grant form
374	/// (`do_write` issues magic grants), the *visible* short write (`do_write`
375	/// deliberately hides it behind [`write_all`]), and the two `CDEV_WRITE` refusals
376	/// a well-formed `write()` never provokes.
377	///
378	/// Four things get proven, in order:
379	///
380	/// 1. **DS lookup.** `tty` was resolved through DS by [`tty_endpoint`] rather than
381	///    hard-coded to `boot_endpoint(TTY_PROC_NR)`, which is what a real client
382	///    does. On failure that helper falls back to the boot endpoint and says so.
383	/// 2. **A real write.** Grant the banner read-only to TTY, send `CDEV_WRITE`, and
384	///    check the reply equals the granted length. `match=1` rather than the length
385	///    itself: self-checking, and it does not have to be re-derived if the banner
386	///    text changes.
387	/// 3. **A short write.** Ask for `CDEV_MAX_IO + 8` bytes and require exactly
388	///    `CDEV_MAX_IO` back. This is the POSIX contract that lets a driver stage
389	///    through a small buffer, and it is the difference between "write returns a
390	///    count" and "write returns success".
391	/// 4. **Two denials.** Each request is valid in every respect but one, so removing
392	///    the corresponding check makes it *succeed* and turns the marker into a
393	///    `FAIL`. See [`cdev_denials`].
394	///
395	/// Best-effort throughout: a failure here must not stop VFS from serving.
396	#[cfg_attr(test, allow(dead_code))]
397	fn tty_demo(grants: &mut GrantPool<GRANT_SLOTS>, tty: Endpoint) {
398	    // 2. The banner, through a read-only direct grant.
399	    let banner_addr = (&raw const TTY_BANNER) as usize as u64;
400	    let banner_len = TTY_BANNER.len() as u64;
401	    let Ok(gid) = grants.grant_direct(tty, banner_addr, banner_len, CPF_READ) else {
402	        return diag_fmt(format_args!("cdev.write FAIL grant"));
403	    };
404	    let rc = cdev_write(tty, CDEV_MINOR_CONSOLE, gid, banner_len as i32, 0);
405	    if rc == banner_len as i32 {
406	        // The reply *is* the byte count, so equality with the granted length is
407	        // the whole assertion. A driver replying `OK` (0) fails this.
408	        diag_fmt(format_args!("cdev.write ok match=1"));
409	    } else {
410	        diag_fmt(format_args!("cdev.write FAIL rc={rc}"));
411	    }
412	    let _ = grants.revoke(gid);
413	
414	    // 3. The short write: more than one call can carry.
415	    let rule_addr = (&raw const TTY_RULE) as usize as u64;
416	    let Ok(rule_gid) = grants.grant_direct(tty, rule_addr, TTY_RULE_LEN as u64, CPF_READ) else {
417	        return diag_fmt(format_args!("cdev.short FAIL grant"));
418	    };
419	    let rc = cdev_write(tty, CDEV_MINOR_CONSOLE, rule_gid, TTY_RULE_LEN as i32, 0);
420	    if rc == CDEV_MAX_IO as i32 {
421	        diag_fmt(format_args!("cdev.short ok n={rc}"));
422	    } else {
423	        diag_fmt(format_args!("cdev.short FAIL rc={rc}"));
424	    }
425	    let _ = grants.revoke(rule_gid);
426	
427	    // 4. The requests that must be refused.
428	    cdev_denials(grants, tty, banner_addr, banner_len);
429	}
430	
431	/// Resolve TTY's endpoint through DS, falling back to its boot endpoint.
432	///
433	/// The lookup is the point — a client should not hard-code a peer's boot proc
434	/// number — but DS publish-before-retrieve is **not** guaranteed by construction.
435	/// It works today because `kernel/build.rs` packs TTY before VFS, so TTY's
436	/// `DS_PUBLISH` reaches DS's FIFO first and completes before VFS's own
437	/// `sef_startup` returns. Rather than let that archive ordering become load-bearing,
438	/// a failed lookup falls back to `boot_endpoint(TTY_PROC_NR)` and emits a
439	/// *distinguishable* diag line: the rest of the demo still runs and still proves the
440	/// CDEV path, while the required `cdev.ds ok` marker disappears and CI goes red on
441	/// the ordering regression specifically.
442	#[cfg_attr(test, allow(dead_code))]
443	fn tty_endpoint() -> Endpoint {
444	    let mut key = [0u8; SYS_GETINFO_NAME_LEN];
445	    key[0..3].copy_from_slice(b"tty");
446	    match sef_retrieve_from_ds(&key) {
447	        Ok(ep) => {
448	            diag_fmt(format_args!("cdev.ds ok ep={ep}"));
449	            ep
450	        }
451	        Err(rc) => {
452	            let ep = boot_endpoint(TTY_PROC_NR);
453	            diag_fmt(format_args!("cdev.ds FAIL rc={rc} fallback={ep}"));
454	            ep
455	        }
456	    }
457	}
458	
459	/// Probe the two `CDEV_WRITE` refusals that no successful write exercises.
460	///
461	/// Slice 5.1's lesson, again: a check no marker exercises is a check that can
462	/// regress silently. Each probe is well-formed in every respect but one.
463	///
464	///   - `bad-minor` — a perfectly good grant aimed at minor 7. The driver's own
465	///     minor check is the only thing that stops it, and the answer is `ENXIO`
466	///     because the *device* does not exist; nothing is wrong with the grant.
467	///   - `not-mine` — a grant over the same bytes, issued to **PM** instead of TTY.
468	///     TTY passes it to `SYS_SAFECOPY` in good faith and the *kernel* refuses it,
469	///     on `verify_grant`'s `who_to == caller's stored endpoint` check. `EPERM`,
470	///     and it is the check that makes a grant id safe to pass around at all: a
471	///     leaked id is useless to anyone but its named grantee.
472	#[cfg_attr(test, allow(dead_code))]
473	fn cdev_denials(grants: &mut GrantPool<GRANT_SLOTS>, tty: Endpoint, addr: u64, len: u64) {
474	    let (Ok(good), Ok(not_mine)) = (
475	        grants.grant_direct(tty, addr, len, CPF_READ),
476	        grants.grant_direct(boot_endpoint(PM_PROC_NR), addr, len, CPF_READ),
477	    ) else {
478	        return diag_fmt(format_args!("cdev.deny FAIL setup"));
479	    };
480	
481	    let probes: [(&str, i32, i32, i32); 2] = [
482	        ("bad-minor", 7, good, ENXIO),
483	        ("not-mine", CDEV_MINOR_CONSOLE, not_mine, EPERM),
484	    ];
485	
486	    let mut denied = 0usize;
487	    for (name, minor, gid, want) in probes {
488	        let rc = cdev_write(tty, minor, gid, len as i32, 0);
489	        if rc == want {
490	            denied += 1;
491	        } else {
492	            diag_fmt(format_args!("cdev.deny FAIL {name} rc={rc}"));
493	        }
494	    }
495	    if denied == probes.len() {
496	        diag_fmt(format_args!("cdev.deny ok n={denied}"));
497	    }
498	    let _ = grants.revoke(good);
499	    let _ = grants.revoke(not_mine);
500	}
501	
502	/// Issue one `CDEV_WRITE` to `tty` and return the reply `m_type` — the byte count
503	/// written, or a negative errno.
504	///
505	/// No granter goes in the payload: TTY takes it from the kernel-stamped `m_source`,
506	/// so this message cannot aim TTY's privileged `SYS_SAFECOPY` anywhere but VFS's own
507	/// address space.
508	#[cfg_attr(test, allow(dead_code))]
509	fn cdev_write(tty: Endpoint, minor: i32, gid: i32, len: i32, offset: u64) -> i32 {
510	    let mut m = Message {
511	        m_source: 0,
512	        m_type: CDEV_WRITE,
513	        payload: [0u8; 96],
514	    };
515	    wr_i32(&mut m, CDEV_MINOR_OFF, minor);
516	    wr_i32(&mut m, CDEV_GRANT_OFF, gid);
517	    wr_i32(&mut m, CDEV_LEN_OFF, len);
518	    wr_u64(&mut m, CDEV_OFFSET_OFF, offset);
519	    let trap_rc = ipc_sendrec(tty, &mut m);
520	    if trap_rc != OK {
521	        return trap_rc;
522	    }
523	    m.m_type
524	}
525	
526	// ----- Slice 5.7: the BDEV ramdisk demo -------------------------------------
527	
528	/// Bytes each block probe moves: the image header's length, which is also the
529	/// tail label's.
530	///
531	/// Small on purpose. VFS's stack is one page, so a whole-block (4096-byte) local
532	/// would run it off the end and fault into VM's out-of-region SIGSEGV arm — which
533	/// prints no `!!! EL0 data abort` for the forbidden list to catch. That is the
534	/// slice-5.5 lesson, and it is why this demo does not read a superblock (which
535	/// starts at byte 1024) either.
536	const BDEV_PROBE_LEN: usize = IMAGE_HDR_LEN;
537	
538	/// One denial probe: a request that is well-formed in every respect but one.
539	#[cfg_attr(test, allow(dead_code))]
540	struct Probe {
541	    name: &'static str,
542	    m_type: i32,
543	    minor: i32,
544	    gid: i32,
545	    len: i32,
546	    block: u64,
547	    want: i32,
548	}
549	
550	/// Resolve the `memory` driver's endpoint through DS, falling back to its boot
551	/// endpoint.
552	///
553	/// A copy of [`tty_endpoint`], and it carries the same contract: the lookup is the
554	/// point, but DS publish-before-retrieve is **not** guaranteed by construction — it
555	/// works because `kernel/build.rs` packs `memory` before `vfs`. So a failed lookup
556	/// falls back and emits a *distinguishable* line: the rest of the demo still runs
557	/// and still proves the BDEV path, while the required `bdev.ds ok` marker
558	/// disappears and CI goes red on the ordering regression specifically.
559	#[cfg_attr(test, allow(dead_code))]
560	fn mem_endpoint() -> Endpoint {
561	    let mut key = [0u8; SYS_GETINFO_NAME_LEN];
562	    key[0..6].copy_from_slice(b"memory");
563	    match sef_retrieve_from_ds(&key) {
564	        Ok(ep) => {
565	            diag_fmt(format_args!("bdev.ds ok ep={ep}"));
566	            ep
567	        }
568	        Err(rc) => {
569	            let ep = boot_endpoint(MEM_PROC_NR);
570	            diag_fmt(format_args!("bdev.ds FAIL rc={rc} fallback={ep}"));
571	            ep
572	        }
573	    }
574	}
575	
576	/// Slice 5.7 demo: read the ramdisk's first and last blocks over `BDEV_READ`.
577	///
578	/// **Why a live client at all**, when slice 5.8 is what really needs BDEV: there is
579	/// no successful `SAFECOPY_TO` anywhere else in the tree. Its only other uses are
580	/// PM's two denial probes, which expect `EPERM` and `EFAULT`. `BDEV_READ` is the
581	/// first copy that writes *into* a grantee's buffer and succeeds, so without this
582	/// the kernel's `CPF_WRITE` + `Prot::writable` success path would stay unproven
583	/// until 5.8 — which would then be debugging a new protocol, a new server, and a
584	/// never-exercised copy direction simultaneously. The anti-spoof rule (the absence
585	/// of a granter field) also cannot be host-tested, and `EROFS`-vs-`ENOSYS` is just
586	/// a comment until something observes the difference.
587	///
588	/// Four things get proven, in order:
589	///
590	/// 1. **DS lookup**, by [`mem_endpoint`] above.
591	/// 2. **A real read.** The reply *is* the byte count, so `n=32` fails for a driver
592	///    that replied `OK`.
593	/// 3. **The header survived** IPC, the grant, and the safecopy.
594	/// 4. **The `block` field reached the right page.** Head and tail do not subsume
595	///    each other: a driver that ignored `block` would return the header for both,
596	///    and the *driver's* own `tail=1` check proves only that the kernel's copy loop
597	///    reached the end of the blob, not that BDEV indexes into it correctly.
598	///
599	/// The granted buffer is a **local**, not a `static`: the driver writes into it, and
600	/// VFS's other granted buffers are all `.rodata` (right for `CPF_READ`, and the
601	/// kernel's `Prot::writable` check would refuse a copy into one).
602	///
603	/// Best-effort throughout: a failure here must not stop VFS from serving.
604	#[cfg_attr(test, allow(dead_code))]
605	fn bdev_demo(grants: &mut GrantPool<GRANT_SLOTS>, mem: Endpoint) {
606	    let mut buf = [0u8; BDEV_PROBE_LEN];
607	    let addr = buf_addr(&mut buf);
608	    let len = BDEV_PROBE_LEN as u64;
609	
610	    // `CPF_WRITE`, because the driver copies *into* this buffer. That direction is
611	    // what makes this the first live exercise of the kernel's write-side grant
612	    // checks.
613	    let Ok(gid) = grants.grant_direct(mem, addr, len, CPF_WRITE) else {
614	        return diag_fmt(format_args!("bdev.read FAIL grant"));
615	    };
616	
617	    // 2 + 3. Block 0: the image header.
618	    let rc = bdev_request(mem, BDEV_READ, BDEV_MINOR_RAMDISK, gid, len as i32, 0);
619	    if rc == len as i32 {
620	        diag_fmt(format_args!("bdev.read ok n={rc}"));
621	    } else {
622	        diag_fmt(format_args!("bdev.read FAIL rc={rc}"));
623	    }
624	    if buf[..IMAGE_LABEL_LEN] == IMAGE_LABEL {
625	        diag_fmt(format_args!("bdev.head ok match=1"));
626	    } else {
627	        diag_fmt(format_args!("bdev.head FAIL"));
628	    }
629	
630	    // 4. The last block: the tail label, which differs from the header's. Zero the
631	    // buffer first — otherwise a read that moved nothing at all would leave the
632	    // header bytes in place and the comparison below would be against stale data
633	    // rather than against what the driver returned.
634	    buf = [0u8; BDEV_PROBE_LEN];
635	    let rc = bdev_request(
636	        mem,
637	        BDEV_READ,
638	        BDEV_MINOR_RAMDISK,
639	        gid,
640	        len as i32,
641	        u64::from(ROOTFS_TAIL_BLOCK),
642	    );
643	    if rc == len as i32 && buf[..IMAGE_LABEL_LEN] == IMAGE_TAIL_LABEL {
644	        diag_fmt(format_args!("bdev.tail ok match=1"));
645	    } else {
646	        diag_fmt(format_args!("bdev.tail FAIL rc={rc}"));
647	    }
648	    let _ = grants.revoke(gid);
649	
650	    bdev_denials(grants, mem, addr);
651	}
652	
653	/// Probe every `BDEV_READ` refusal that a successful read does not exercise.
654	///
655	/// Slice 5.1's lesson, again: a check no marker exercises is a check that can
656	/// regress silently. Each probe is well-formed in every respect but one.
657	///
658	///   - `bad-minor` — a good grant aimed at minor 7. The driver's own minor check
659	///     is the only thing that stops it: `ENXIO`, because the *device* does not
660	///     exist; nothing is wrong with the grant.
661	///   - `bad-block` — one block past the end. `EINVAL` rather than `EIO`: the
662	///     device's size is known to its client, so this is a caller bug.
663	///   - `too-long` — one byte more than [`BDEV_MAX_IO`]. The deliberate departure
664	///     from CDEV: `EINVAL`, not a short read.
665	///   - `neg-len` — a negative length, which unchecked would widen into a ~16 EiB
666	///     `u64` byte count for the kernel copy.
667	///   - `not-mine` — the same bytes granted to **PM** instead of the driver. The
668	///     driver passes it to `SYS_SAFECOPY` in good faith and the *kernel* refuses
669	///     it, on `verify_grant`'s `who_to` check.
670	///   - `read-only` — a `CPF_READ`-only grant used as a copy *destination*.
671	///     **The access mask in the write direction, which slice 5.3 never
672	///     exercised**: every grant in the tree until now was read-side.
673	///   - `write` — `BDEV_WRITE`, which must answer `EROFS`. Fold that arm into the
674	///     driver's `_` case and this becomes `ENOSYS`, which is the whole reason the
675	///     request has a number of its own.
676	///   - `unknown` — a request one past the band. `ENOSYS`, and **the reply itself is
677	///     the assertion**: a driver that dropped an unknown request would leave VFS
678	///     blocked in its SENDREC forever and take every later marker with it.
679	///
680	/// Plus one probe that is not a BDEV request at all: `SYS_GETINFO(GET_RAMDISK)`
681	/// issued by VFS, which the kernel must refuse with `EPERM`. The ramdisk is mapped
682	/// into exactly one address space, so that gate is what stops the VA being handed
683	/// to a process where it faults — and VFS, a `SYS_PROC` server that holds the call,
684	/// is the strongest caller available to test it with.
685	#[cfg_attr(test, allow(dead_code))]
686	fn bdev_denials(grants: &mut GrantPool<GRANT_SLOTS>, mem: Endpoint, addr: u64) {
687	    let len = BDEV_PROBE_LEN as u64;
688	    let (Ok(good), Ok(not_mine), Ok(read_only)) = (
689	        grants.grant_direct(mem, addr, len, CPF_WRITE),
690	        grants.grant_direct(boot_endpoint(PM_PROC_NR), addr, len, CPF_WRITE),
691	        grants.grant_direct(mem, addr, len, CPF_READ),
692	    ) else {
693	        return diag_fmt(format_args!("bdev.deny FAIL setup"));
694	    };
695	
696	    let n = len as i32;
697	    let probes = [
698	        Probe {
699	            name: "bad-minor",
700	            m_type: BDEV_READ,
701	            minor: 7,
702	            gid: good,
703	            len: n,
704	            block: 0,
705	            want: ENXIO,
706	        },
707	        Probe {
708	            name: "bad-block",
709	            m_type: BDEV_READ,
710	            minor: BDEV_MINOR_RAMDISK,
711	            gid: good,
712	            len: n,
713	            block: u64::from(ROOTFS_IMAGE_BLOCKS),
714	            want: EINVAL,
715	        },
716	        Probe {
717	            name: "too-long",
718	            m_type: BDEV_READ,
719	            minor: BDEV_MINOR_RAMDISK,
720	            gid: good,
721	            len: BDEV_MAX_IO as i32 + 1,
722	            block: 0,
723	            want: EINVAL,
724	        },
725	        Probe {
726	            name: "neg-len",
727	            m_type: BDEV_READ,
728	            minor: BDEV_MINOR_RAMDISK,
729	            gid: good,
730	            len: -1,
731	            block: 0,
732	            want: EINVAL,
733	        },
734	        Probe {
735	            name: "not-mine",
736	            m_type: BDEV_READ,
737	            minor: BDEV_MINOR_RAMDISK,
738	            gid: not_mine,
739	            len: n,
740	            block: 0,
741	            want: EPERM,
742	        },
743	        Probe {
744	            name: "read-only",
745	            m_type: BDEV_READ,
746	            minor: BDEV_MINOR_RAMDISK,
747	            gid: read_only,
748	            len: n,
749	            block: 0,
750	            want: EPERM,
751	        },
752	        Probe {
753	            name: "write",
754	            m_type: BDEV_WRITE,
755	            minor: BDEV_MINOR_RAMDISK,
756	            gid: good,
757	            len: n,
758	            block: 0,
759	            want: EROFS,
760	        },
761	        // A write to a device that does not exist. `ENXIO`, not `EROFS`: the
762	        // driver validates the request before refusing it, so it never asserts
763	        // read-onlyness about a device it does not have. Without this probe the
764	        // `BDEV_WRITE` arm could be reduced back to a bare `EROFS` and no marker
765	        // would move.
766	        Probe {
767	            name: "write-bad-minor",
768	            m_type: BDEV_WRITE,
769	            minor: 7,
770	            gid: good,
771	            len: n,
772	            block: 0,
773	            want: ENXIO,
774	        },
775	        Probe {
776	            name: "unknown",
777	            m_type: BDEV_RQ_BASE + NR_BDEV_MSGS as i32,
778	            minor: BDEV_MINOR_RAMDISK,
779	            gid: good,
780	            len: n,
781	            block: 0,
782	            want: ENOSYS,
783	        },
784	    ];
785	
786	    let mut denied = 0usize;
787	    for p in &probes {
788	        let rc = bdev_request(mem, p.m_type, p.minor, p.gid, p.len, p.block);
789	        if rc == p.want {
790	            denied += 1;
791	        } else {
792	            diag_fmt(format_args!("bdev.deny FAIL {} rc={rc}", p.name));
793	        }
794	    }
795	
796	    // The kernel's own gate, which no BDEV message can reach.
797	    let mut m = Message {
798	        m_source: 0,
799	        m_type: 0,
800	        payload: [0u8; 96],
801	    };
802	    let rc = sys_getinfo(GET_RAMDISK, &mut m);
803	    if rc == EPERM {
804	        denied += 1;
805	    } else {
806	        diag_fmt(format_args!("bdev.deny FAIL getinfo rc={rc}"));
807	    }
808	
809	    if denied == probes.len() + 1 {
810	        diag_fmt(format_args!("bdev.deny ok n={denied}"));
811	    }
812	    for gid in [good, not_mine, read_only] {
813	        let _ = grants.revoke(gid);
814	    }
815	}
816	
817	/// Issue one block-device request and return the reply `m_type` — the byte count
818	/// read, or a negative errno.
819	///
820	/// `m_type` is a parameter rather than hardcoded to `BDEV_READ` so the `BDEV_WRITE`
821	/// and unknown-request probes ride the same marshaling as a real read; a probe
822	/// built by a second, hand-written marshaller would prove less.
823	///
824	/// No granter goes in the payload — the driver takes it from the kernel-stamped
825	/// `m_source`, so this message cannot aim the driver's privileged `SYS_SAFECOPY`
826	/// anywhere but VFS's own address space. There is no grant-offset field either.
827	#[cfg_attr(test, allow(dead_code))]
828	fn bdev_request(mem: Endpoint, m_type: i32, minor: i32, gid: i32, len: i32, block: u64) -> i32 {
829	    let mut m = Message {
830	        m_source: 0,
831	        m_type,
832	        payload: [0u8; 96],
833	    };
834	    wr_i32(&mut m, BDEV_MINOR_OFF, minor);
835	    wr_i32(&mut m, BDEV_GRANT_OFF, gid);
836	    wr_i32(&mut m, BDEV_LEN_OFF, len);
837	    wr_u64(&mut m, BDEV_BLOCK_OFF, block);
838	    let trap_rc = ipc_sendrec(mem, &mut m);
839	    if trap_rc != OK {
840	        return trap_rc;
841	    }
842	    m.m_type
843	}
844	
845	/// SEF fresh-init callback: publish VFS's endpoint to DS under its name. DS
846	/// registers the caller's kernel-stamped endpoint, so `_endpoint` from
847	/// `GET_WHOAMI` is not sent.
848	#[cfg_attr(test, allow(dead_code))]
849	fn vfs_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
850	    sef_publish_to_ds(name)
851	}
852	
853	// The freestanding panic handler; under `cargo test` std supplies its own.
854	#[cfg(not(test))]
855	#[panic_handler]
856	fn panic(_: &core::panic::PanicInfo) -> ! {
857	    loop {
858	        core::hint::spin_loop()
859	    }
860	}
