141	    use super::*;
142	    use minixrs_kernel_shared::callnr::CDEV_MAX_IO;
143	    use minixrs_server_rt::{wr_i32, wr_u64};
144	
145	    /// A plausible user buffer: non-zero and well inside the user range.
