// Boot image.
// ---------------------------------------------------------------------------

struct BootEntry {
    nr: ProcNr,
    name: &'static [u8],
    priv_flags: u16,
    trap_mask: u16,
    priority: u8,
    quantum_ms: u32,
    runnable: bool,
}

const N_IMAGE: usize = NR_TASKS + NR_BOOT_PROCS;
const _: () = assert!(N_IMAGE == 16);

static IMAGE: [BootEntry; N_IMAGE] = [
    // --- Kernel tasks (always runnable) -----------------------------------
    BootEntry {
        nr: ASYNCM,
        name: b"asyncm",
        priv_flags: SYS_PROC,
        trap_mask: TSK_T,
        priority: TASK_Q,
        quantum_ms: 0,
        runnable: true,
    },
    BootEntry {
        nr: IDLE,
        name: b"idle",
        priv_flags: SYS_PROC | BILLABLE,
        trap_mask: TSK_T,
        priority: IDLE_Q,
        quantum_ms: 0,
        runnable: true,
    },
    BootEntry {
        nr: CLOCK,
        name: b"clock",
        priv_flags: SYS_PROC,
        trap_mask: CSK_T,
        priority: TASK_Q,
        quantum_ms: 0,
        runnable: true,
    },
    BootEntry {
        nr: SYSTEM,
        name: b"system",
        priv_flags: SYS_PROC,
        trap_mask: CSK_T,
        priority: TASK_Q,
        quantum_ms: 0,
        runnable: true,
    },
    BootEntry {
        nr: HARDWARE,
        name: b"hardware",
        priv_flags: SYS_PROC,
        trap_mask: TSK_T,
        priority: TASK_Q,
        quantum_ms: 0,
        runnable: true,
    },
    // --- Boot servers (blocked on RTS_NO_PRIV until slice 2.6 loads ELFs) -
    BootEntry {
        nr: PM_PROC_NR,
        name: b"pm",
        priv_flags: SYS_PROC | PREEMPTIBLE,
        trap_mask: SRV_T,
        priority: SRV_Q,
        quantum_ms: SRV_QUANTUM_MS,
        runnable: false,
    },
    BootEntry {
        nr: VFS_PROC_NR,
        name: b"vfs",
        priv_flags: SYS_PROC | PREEMPTIBLE,
        trap_mask: SRV_T,
        priority: SRV_Q,
        quantum_ms: SRV_QUANTUM_MS,
        runnable: false,
    },
    BootEntry {
        nr: RS_PROC_NR,
        name: b"rs",
