    use super::*;
    use minixrs_kernel_shared::callnr::FS_MAX_IO;
    use minixrs_kernel_shared::inode_mode_probe::{I_DIRECTORY, I_REGULAR};

    fn empty() -> Message {
        Message {
            m_source: 0,
            m_type: 0,
            payload: [0u8; 96],
