            *b = b'a';
        }
        assert_eq!(parse_lookup(&m), Err(ENAMETOOLONG));

        // One byte shorter, with the NUL in the last slot, is fine — the
        // boundary itself.
        m.payload[FS_PATH_OFF + FS_PATH_MAX - 1] = 0;
        assert_eq!(parse_lookup(&m).map(str::len), Ok(FS_PATH_MAX - 1));
    }

