        let mut m = empty();
        reply_readsuper(&mut m, 1, 4096, 256);
        assert_eq!(rd_i32(&m, FS_SUPER_ROOT_OFF), 1);
        assert_eq!(rd_i32(&m, FS_SUPER_BLOCK_SIZE_OFF), 4096);
        assert_eq!(rd_i32(&m, FS_SUPER_BLOCKS_OFF), 256);
    }

