        let mut m = empty();
        assert_eq!(rd_i32(&m, 96), 0);
        assert_eq!(rd_i32(&m, usize::MAX), 0);
        assert_eq!(rd_u64(&m, 90), 0);
        wr_i32(&mut m, 96, 7);
        assert!(m.payload.iter().all(|&b| b == 0));
    }
}

