91	const GRANT_SLOTS: usize = 8;
92	
93	/// The granted buffer. A `static` (not `static mut`) so it lands in `.rodata`,
94	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant,
95	/// and it means the kernel's `Prot::writable` check would reject any attempt to
96	/// safecopy *into* it.
97	static GRANT_TEST_BUF: [u8; GRANT_TEST_LEN] = grant_test_pattern();
98	
99	/// A deterministic, non-trivial byte pattern. Deterministic so PM's checksum is
100	/// a fixed value across runs; non-trivial (not `i`, not a constant) so a copy
101	/// that lost or duplicated a chunk still changes the sum.
102	const fn grant_test_pattern() -> [u8; GRANT_TEST_LEN] {
103	    let mut b = [0u8; GRANT_TEST_LEN];
104	    let mut i = 0;
105	    while i < GRANT_TEST_LEN {
106	        b[i] = (i as u8).wrapping_mul(37).wrapping_add(11);
107	        i += 1;
108	    }
109	    b
110	}
111	
112	// ----- Slice 5.3: the CDEV console demo ------------------------------------
113	
114	/// The line VFS asks TTY to print. In `.rodata` (a `static`, not `static mut`),
115	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant.
116	static TTY_BANNER: [u8; 35] = *b"minix.rs vfs: hello via CDEV_WRITE\n";
117	
118	/// Length of the short-write probe: eight bytes past what one `CDEV_WRITE` can
119	/// carry, so the reply must come back clamped.
120	const TTY_RULE_LEN: usize = CDEV_MAX_IO + 8;
121	
122	/// A buffer deliberately longer than [`CDEV_MAX_IO`], whose byte at index
123	/// `CDEV_MAX_IO - 1` is `\n` — so the *clamped* write renders as exactly one
124	/// console line. The eight bytes past the clamp spell `TRUNCATE`, which therefore
125	/// must never appear on the console: if they do, the driver ignored its own limit.
126	static TTY_RULE: [u8; TTY_RULE_LEN] = tty_rule_pattern();
127	
128	const fn tty_rule_pattern() -> [u8; TTY_RULE_LEN] {
129	    let mut b = [b'-'; TTY_RULE_LEN];
130	    let prefix = b"minix.rs vfs: short-write rule ";
131	    let mut i = 0;
132	    while i < prefix.len() {
133	        b[i] = prefix[i];
134	        i += 1;
135	    }
136	    // Ends the line at the clamp boundary.
137	    b[CDEV_MAX_IO - 1] = b'\n';
138	    // Past the clamp: must never reach the console.
139	    let tail = b"TRUNCATE";
140	    let mut j = 0;
141	    while j < tail.len() {
142	        b[CDEV_MAX_IO + j] = tail[j];
143	        j += 1;
144	    }
145	    b
146	}
