1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! The FS band on the wire: parsing requests and building replies (slice 5.8).
4	//!
5	//! Everything here is a total function over a [`Message`], so it carries unit
6	//! tests while the IPC round trip lives in `main.rs` — the `servers/ds`
7	//! `registry.rs` / `main.rs` split, and the same reason: `main.rs` is behind
8	//! `required-features = ["server"]` and therefore invisible to every CI job, so
9	//! anything with a decision in it belongs here.
10	//!
11	//! ## Why this crate has its own payload accessors
12	//!
13	//! `server-rt`'s `rd_i32` / `rd_u64` are the same six lines, but `server-rt` is an
14	//! **optional** dependency of this crate (it comes in with the `server` feature),
15	//! and this module is not. Re-deriving them costs a dozen lines and buys the test
16	//! that catches a swapped payload offset — the trade `userland/init` already
17	//! makes for exactly the same reason.
18	//!
19	//! ## The path is inline, and that is the interesting part
20	//!
21	//! [`parse_lookup`] reads the path out of a **fixed, NUL-padded** field rather
22	//! than through a grant. It is control plane rather than the data path grants
23	//! were provisioned for, it costs this server no staging buffer (its scarcest
24	//! resource — one 4 KiB block buffer is already the whole stack), and it deletes
25	//! the confused-deputy question outright, because a request with no granter
26	//! cannot aim one anywhere. The cost is the cap, and it is paid here: a path that
27	//! fills its field with no NUL is `ENAMETOOLONG`, never a truncated path that
28	//! resolves to some other file.
29	
30	use minixrs_kernel_shared::Message;
31	use minixrs_kernel_shared::callnr::{
32	    FS_GRANT_OFF, FS_INO_OFF, FS_LEN_OFF, FS_MODE_OFF, FS_PATH_MAX, FS_PATH_OFF, FS_POS_OFF,
33	    FS_SIZE_OFF, FS_SUPER_BLOCK_SIZE_OFF, FS_SUPER_BLOCKS_OFF, FS_SUPER_MINOR_OFF,
34	    FS_SUPER_ROOT_OFF,
35	};
36	use minixrs_kernel_shared::error::{EINVAL, ENAMETOOLONG};
37	
38	/// A parsed [`FS_READ`](minixrs_kernel_shared::callnr::FS_READ) request.
39	///
40	/// Field-for-field the payload, with no interpretation applied — the checks live
41	/// in [`crate::walk::clamp_read`] and in the server's inode lookup. There is
42	/// deliberately **no granter field**: the server takes the granter from the
43	/// kernel-stamped `m_source`, so this struct has no way to express one.
44	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
45	pub struct ReadRequest {
46	    /// The inode to read, as handed out by a previous `FS_LOOKUP`.
47	    pub ino: i32,
48	    /// Grant id over the destination buffer. Must carry `CPF_WRITE` and name this
49	    /// server as grantee; the kernel checks both.
50	    pub gid: i32,
51	    /// Bytes asked for. Clamped, not refused — see [`crate::walk::clamp_read`].
52	    pub len: i32,
53	    /// Byte offset within the file.
54	    pub pos: u64,
55	}
56	
57	/// Read the block-device minor out of an `FS_READSUPER` request.
58	pub fn parse_readsuper(msg: &Message) -> i32 {
59	    rd_i32(msg, FS_SUPER_MINOR_OFF)
60	}
61	
62	/// Read the path out of an `FS_LOOKUP` request.
63	///
64	/// The field is [`FS_PATH_MAX`] bytes, NUL-**padded**: the server reads the whole
65	/// fixed width and stops at the first NUL, so bytes past the terminator cannot
66	/// leak between requests.
67	///
68	/// Three ways it can fail, and each is a different thing to tell a client:
69	///
70	///   * no NUL anywhere in the field → `ENAMETOOLONG`. Never a silently truncated
71	///     path, which could resolve to a different file than the one asked for.
72	///   * not valid UTF-8 → `EINVAL`. minix.rs paths are UTF-8 by construction (they
73	///     come from a Rust `&str` at the other end), so this is a malformed request.
74	///   * an empty path → `EINVAL`, via [`crate::walk::parse_path`], which the caller
75	///     applies next. Left here it would be indistinguishable from "the client sent
76	///     a zeroed payload", which it is.
77	pub fn parse_lookup(msg: &Message) -> Result<&str, i32> {
78	    let field = &msg.payload[FS_PATH_OFF..FS_PATH_OFF + FS_PATH_MAX];
79	    let end = field.iter().position(|&b| b == 0).ok_or(ENAMETOOLONG)?;
80	    core::str::from_utf8(&field[..end]).map_err(|_| EINVAL)
81	}
82	
83	/// Read an `FS_READ` request out of a message payload.
84	///
85	/// Total: every field is a fixed-offset scalar read that cannot fail (an
86	/// out-of-range offset reads as `0`), so a malformed request becomes an invalid
87	/// *value* the checks reject, never a panic.
88	pub fn parse_read(msg: &Message) -> ReadRequest {
89	    ReadRequest {
90	        ino: rd_i32(msg, FS_INO_OFF),
91	        gid: rd_i32(msg, FS_GRANT_OFF),
92	        len: rd_i32(msg, FS_LEN_OFF),
93	        pos: rd_u64(msg, FS_POS_OFF),
94	    }
95	}
96	
97	/// Build the payload of a successful `FS_READSUPER` reply.
98	///
99	/// The caller stamps `m_type` (`OK`). These three are what make the reply worth
100	/// more than its `m_type`: a boot marker can cross-check them against the
101	/// *device*'s independently derived geometry.
102	pub fn reply_readsuper(msg: &mut Message, root: u32, block_size: usize, blocks: u32) {
103	    msg.payload = [0u8; 96];
104	    wr_i32(msg, FS_SUPER_ROOT_OFF, root as i32);
105	    wr_i32(msg, FS_SUPER_BLOCK_SIZE_OFF, block_size as i32);
106	    wr_i32(msg, FS_SUPER_BLOCKS_OFF, blocks as i32);
107	}
108	
109	/// Build the payload of a successful `FS_LOOKUP` reply.
110	///
111	/// `mode` is widened from MinixFS's `u16` so the wire field is an ordinary i32
112	/// like every other; the type bits a client cares about (`S_IFDIR`, `S_IFREG`)
113	/// are well inside 16 bits, so nothing is lost. `size` is already the inode's own
114	/// signed size.
115	pub fn reply_lookup(msg: &mut Message, ino: u32, mode: u16, size: i32) {
116	    msg.payload = [0u8; 96];
117	    wr_i32(msg, FS_INO_OFF, ino as i32);
118	    wr_i32(msg, FS_MODE_OFF, i32::from(mode));
119	    wr_i32(msg, FS_SIZE_OFF, size);
120	}
121	
122	/// Read a native-endian `i32` from a payload offset. `0` past the end.
123	///
124	/// `checked_add`, not `+`: `[profile.release]` sets `overflow-checks = false`, so
125	/// `off + 4` on a huge offset *wraps* in the shipped binary — where it would be
126	/// safe only by accident, via a `None` from `get` — while panicking under
127	/// `cargo test`. Being explicit makes both profiles agree, which is the
128	/// workspace-wide rule for offset arithmetic in a server.
129	fn rd_i32(m: &Message, off: usize) -> i32 {
130	    match off.checked_add(4).and_then(|end| m.payload.get(off..end)) {
131	        Some(b) => i32::from_ne_bytes([b[0], b[1], b[2], b[3]]),
132	        None => 0,
133	    }
134	}
135	
136	/// Read a native-endian `u64` from a payload offset. `0` past the end.
137	fn rd_u64(m: &Message, off: usize) -> u64 {
138	    match off.checked_add(8).and_then(|end| m.payload.get(off..end)) {
139	        Some(b) => u64::from_ne_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]]),
140	        None => 0,
141	    }
142	}
143	
144	/// Write a native-endian `i32` to a payload offset. A no-op past the end.
145	fn wr_i32(m: &mut Message, off: usize, v: i32) {
146	    if let Some(b) = off
147	        .checked_add(4)
148	        .and_then(|end| m.payload.get_mut(off..end))
149	    {
150	        b.copy_from_slice(&v.to_ne_bytes());
151	    }
152	}
