// 96-byte payload. `VFS_BUF_OFF` is 8 wide (u64); the rest are 4 (i32).
const _: () = assert!(VFS_FD_OFF + 4 <= VFS_LEN_OFF);
const _: () = assert!(VFS_LEN_OFF + 4 <= VFS_BUF_OFF);
const _: () = assert!(VFS_BUF_OFF + 8 <= 96);
