    fn a_descriptor_past_the_end_of_the_row_is_ebadf() {
        for fd in [NR_FDS as i32, NR_FDS as i32 + 1, 64, i32::MAX] {
            assert_eq!(resolve(0, fd), Err(EBADF), "fd {fd}");
