3	//! `VFS_OPEN` request parsing, validation, and the classification of what
4	//! `FS_LOOKUP` came back with (slice 5.8).
5	//!
6	//! A sibling of `rw.rs` rather than a part of it, because almost nothing is
7	//! shared: `open` takes a *path* where read and write take a descriptor, and its
8	//! whole job is turning what the filesystem said about an inode into either a
9	//! descriptor or an errno. Everything here is a total function over plain values,
10	//! so it carries the crate's unit tests while the IPC round trip lives in
11	//! `main.rs` — the `drivers/tty` `cdev.rs` / `main.rs` split.
12	//!
13	//! ## The path arrives as an address, and VFS reads it itself
14	//!
15	//! `VFS_OPEN`'s client is an ordinary user process with no grant table, so the
16	//! payload carries a raw buffer address. VFS copies the bytes out with `SYS_COPY`
17	//! — **the first live consumer of decision D4's "`SYS_COPY` for control plane"
18	//! sentence**, and the confused-deputy rule in its sharpest form: `SYS_COPY` has
19	//! *no per-target authorization at all*, so a payload-supplied source process
20	//! would let any client read any process's memory through VFS. The source is the
21	//! kernel-stamped `m_source`, and there is no field for it.
22	//!
23	//! That copy is `main.rs`'s business. What lives here is deciding whether the
24	//! request is worth making it for ([`validate`]) and what to do with the answer
25	//! ([`classify`]).
26	
27	use minixrs_kernel_shared::Message;
28	use minixrs_kernel_shared::callnr::{FS_PATH_MAX, VFS_PATH_LEN_OFF, VFS_PATH_OFF};
29	use minixrs_kernel_shared::error::{EFAULT, EINVAL, EISDIR, ENAMETOOLONG};
30	use minixrs_kernel_shared::message::user_range_ok;
31	use minixrs_server_rt::{rd_i32, rd_u64};
32	
33	use crate::fd::Fd;
34	
35	/// A parsed `VFS_OPEN` request. Field-for-field the payload, with no
36	/// interpretation applied.
37	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
38	pub struct OpenRequest {
39	    /// The path buffer's address **in the caller's own address space**.
40	    pub path: u64,
41	    /// Its length in bytes, not counting any terminator the caller may have.
42	    pub len: i32,
43	}
44	
45	/// Read a `VFS_OPEN` request out of a message payload.
46	///
47	/// Total: both fields are fixed-offset scalar reads that cannot fail, so a
48	/// malformed request becomes an invalid *value* the checks reject, never a panic.
49	pub fn parse(msg: &Message) -> OpenRequest {
50	    OpenRequest {
51	        path: rd_u64(msg, VFS_PATH_OFF),
52	        len: rd_i32(msg, VFS_PATH_LEN_OFF),
53	    }
54	}
55	
56	/// Decide how many path bytes to copy in, or which errno to reply.
57	///
58	/// The checks, in order — each is the first thing that can be wrong given the
59	/// ones before it:
60	///
61	/// 1. `len <= 0` → `EINVAL`. Unlike a read or a write, an **empty path is not a
62	///    legal no-op**: there is no file it could name. Negative is the same class of
63	///    bug it is everywhere else — left unchecked it would widen into a ~16 EiB
64	///    `u64` on the copy.
65	/// 2. `len >= FS_PATH_MAX` → `ENAMETOOLONG`, **refused before the wire**. The FS
66	///    band carries the path inline in a fixed, NUL-padded field, so the longest
67	///    path that can travel is one byte shorter than the field — and catching it
68	///    here means the client hears a specific errno without a round trip, rather
69	///    than a truncated path resolving to some other file.
70	/// 3. The buffer lies in the user address range → else `EFAULT`. `user_range_ok`,
71	///    the no-alignment variant, since a path is a byte buffer. Defence in depth
72	///    rather than the load-bearing gate: the kernel's copy engine walks the
73	///    caller's page tables and answers `EFAULT` regardless (D5).
74	pub fn validate(len: i32, path: u64) -> Result<usize, i32> {
75	    if len <= 0 {
76	        return Err(EINVAL);
77	    }
78	    let len = len as usize;
79	    if len >= FS_PATH_MAX {
80	        return Err(ENAMETOOLONG);
81	    }
82	    if !user_range_ok(path, len as u64) {
83	        return Err(EFAULT);
84	    }
85	    Ok(len)
86	}
87	
88	/// Turn an `FS_LOOKUP` reply's mode into the descriptor entry to install, or the
89	/// errno to reply.
90	///
91	/// Two answers, and the second is the one worth having:
92	///
93	/// * A **regular file** becomes an [`Fd::File`] at position 0.
94	/// * A **directory** is `EISDIR`. Not `EINVAL`, and not silently opened: there is
95	///   no `O_DIRECTORY` and nothing that could read one (no `GETDENTS`), so a
96	///   descriptor onto a directory would be a descriptor every subsequent `read`
97	///   had to refuse. Saying so at `open` is both the POSIX-shaped answer and the
98	///   one that keeps `read`'s own `EISDIR` arm from being the only line of defence.
99	/// * Anything else — a device node, a symlink, a mode this build does not
100	///   recognize — is `EINVAL`. `mkfs-mfs` writes none of them, so this arm exists
101	///   to make an unrecognized mode a refusal rather than a file.
102	///
103	/// The mode arrives as an i32 widened from MinixFS's `u16`, so it is masked back
104	/// down before the type bits are read.
105	pub fn classify(mode: i32) -> Result<Fd, i32> {
106	    const I_TYPE: u16 = 0o170000;
107	    const I_REGULAR: u16 = 0o100000;
108	    const I_DIRECTORY: u16 = 0o040000;
109	
110	    match (mode as u16) & I_TYPE {
111	        I_REGULAR => Ok(Fd::File { ino: 0, pos: 0 }),
112	        I_DIRECTORY => Err(EISDIR),
113	        _ => Err(EINVAL),
114	    }
115	}
